/* ==========================================================================
   MOIST INTRAMURALS 2026-2027 - PRE-BUILT FRONTEND ENGINE (SUPABASE POWERED)
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {

  const SUPABASE_URL = 'https://lfloyhdkrvpfgvvlppah.supabase.co';
  const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImxmbG95aGRrcnZwZmd2dmxwcGFoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk3Nzk0NTQsImV4cCI6MjEwNTM1NTQ1NH0.Kpme7uzC6xy69HMr31X57AGJTDpYKuJiwweoXhmjZWQ';

  const HEADERS = {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Content-Type': 'application/json'
  };

  // 1. CANVAS FIREWORKS ENGINE
  const canvas = document.getElementById('fx-canvas');
  const ctx = canvas.getContext('2d');

  let width = (canvas.width = window.innerWidth);
  let height = (canvas.height = window.innerHeight);

  window.addEventListener('resize', () => {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  });

  const particles = [];
  const ambientStars = [];

  for (let i = 0; i < 45; i++) {
    ambientStars.push({
      x: Math.random() * width, y: Math.random() * height,
      size: Math.random() * 2 + 1, speed: Math.random() * 0.5 + 0.2, opacity: Math.random()
    });
  }

  class Particle {
    constructor(x, y, color) {
      this.x = x; this.y = y; this.color = color;
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 9 + 2;
      this.vx = Math.cos(angle) * speed;
      this.vy = Math.sin(angle) * speed;
      this.radius = Math.random() * 4 + 2;
      this.alpha = 1; this.friction = 0.96; this.gravity = 0.14;
    }

    draw() {
      ctx.save(); ctx.globalAlpha = this.alpha;
      ctx.fillStyle = this.color; ctx.shadowBlur = 12; ctx.shadowColor = this.color;
      ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }

    update() {
      this.vx *= this.friction; this.vy *= this.friction;
      this.vy += this.gravity; this.x += this.vx; this.y += this.vy;
      this.alpha -= 0.014;
    }
  }

  function spawnBurst(x, y, count = 75, customColors = null) {
    const defaultColors = ['#ffd700', '#ff3344', '#ffffff', '#ff9900', '#ff0055'];
    const colors = customColors || defaultColors;
    for (let i = 0; i < count; i++) {
      const color = colors[Math.floor(Math.random() * colors.length)];
      particles.push(new Particle(x, y, color));
    }
  }

  function renderFX() {
    ctx.clearRect(0, 0, width, height);

    ambientStars.forEach(star => {
      star.y -= star.speed;
      if (star.y < 0) star.y = height;
      ctx.fillStyle = `rgba(255, 215, 0, ${star.opacity})`;
      ctx.beginPath(); ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2); ctx.fill();
    });

    for (let i = particles.length - 1; i >= 0; i--) {
      particles[i].draw();
      particles[i].update();
      if (particles[i].alpha <= 0) particles.splice(i, 1);
    }
    requestAnimationFrame(renderFX);
  }
  renderFX();

  // 2. BACKGROUND MUSIC & WEB AUDIO SYNTHESIZER
  const bgMusic = new Audio('teeth-bg-music.MP3');
  bgMusic.loop = true;
  bgMusic.volume = 0.85;

  function playBackgroundMusic() {
    bgMusic.play().catch(err => {
      console.warn('Background music play error:', err);
    });
  }

  let audioCtx = null;
  function playFanfareSound() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const now = audioCtx.currentTime;

    const oscBass = audioCtx.createOscillator();
    const gainBass = audioCtx.createGain();
    oscBass.type = 'triangle';
    oscBass.frequency.setValueAtTime(160, now);
    oscBass.frequency.exponentialRampToValueAtTime(30, now + 0.9);
    gainBass.gain.setValueAtTime(0.8, now);
    gainBass.gain.exponentialRampToValueAtTime(0.01, now + 0.9);
    oscBass.connect(gainBass); gainBass.connect(audioCtx.destination);
    oscBass.start(now); oscBass.stop(now + 0.9);

    const notes = [523.25, 659.25, 783.99, 1046.50];
    notes.forEach((freq, index) => {
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now + index * 0.08);
      gain.gain.setValueAtTime(0.01, now + index * 0.08);
      gain.gain.linearRampToValueAtTime(0.35, now + index * 0.08 + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, now + index * 0.08 + 1.3);
      osc.connect(gain); gain.connect(audioCtx.destination);
      osc.start(now + index * 0.08); osc.stop(now + index * 0.08 + 1.3);
    });
  }

  // 3. REVEAL PORTAL HANDLER
  const openBtn = document.getElementById('open-btn');
  const landingScreen = document.getElementById('landing-screen');
  const mainPortal = document.getElementById('main-portal');

  if (openBtn) {
    openBtn.addEventListener('click', () => {
      const rect = openBtn.getBoundingClientRect();
      playBackgroundMusic();
      playFanfareSound();
      spawnBurst(rect.left + rect.width / 2, rect.top + rect.height / 2, 100);
      setTimeout(() => spawnBurst(width * 0.2, height * 0.3, 70), 200);
      setTimeout(() => spawnBurst(width * 0.8, height * 0.3, 70), 400);

      landingScreen.classList.add('fade-out');
      setTimeout(() => {
        landingScreen.style.display = 'none';
        mainPortal.classList.remove('hidden');
        window.scrollTo({ top: 0, behavior: 'smooth' });
        checkTicketsAvailability();
      }, 600);
    });
  }

  // 4. SUPABASE BSIT FREE TICKET SYSTEM
  const bsitTicketBtn = document.getElementById('bsit-ticket-btn');
  const bsitBtnText = document.getElementById('bsit-btn-text');
  const ticketStatusCount = document.getElementById('ticket-status-count');
  const questionCard = document.getElementById('question-card');
  const presidentInput = document.getElementById('president-input');
  const claimBtn = document.getElementById('claim-btn');
  const claimBtnText = document.getElementById('claim-btn-text');
  const ticketResult = document.getElementById('ticket-result');

  // 5 UNIQUE QUESTIONS DATA & CASE-INSENSITIVE VALIDATORS FOR TICKETS 1-5
  const TICKET_QUESTIONS = {
    1: {
      num: 1,
      code: "MOIST-VIP-001",
      question: "Who is the President of MOIST?",
      example: "(e.g. <em>RPH Reynaldo P. Valmores</em> or <em>Reynaldo P. Valmores</em>)",
      placeholder: "e.g. RPH Reynaldo P. Valmores",
      validate: (input) => {
        const clean = input.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[\.\,]/g, '');
        const validAnswers = [
          'rph reynaldo p valmores',
          'reynaldo p valmores',
          'reynaldo valmores'
        ];
        return validAnswers.includes(clean);
      },
      errorHint: "Incorrect President Name! (e.g. RPH Reynaldo P. Valmores or Reynaldo P. Valmores)"
    },
    2: {
      num: 2,
      code: "MOIST-VIP-002",
      question: 'What do the letters "M-O-I-S-T" stand for in the school\'s name?',
      example: "(e.g. <em>MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY INC.</em>)",
      placeholder: "e.g. MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY INC.",
      validate: (input) => {
        const clean = input.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[\.\,]/g, '');
        return clean.includes('misamis oriental institute of science and technology');
      },
      errorHint: "Incorrect answer! (e.g. MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY INC.)"
    },
    3: {
      num: 3,
      code: "MOIST-VIP-003",
      question: "What do you call a student who studies at MOIST?",
      example: "(e.g. <em>MOISTIAN</em>)",
      placeholder: "e.g. MOISTIAN",
      validate: (input) => {
        const clean = input.trim().toLowerCase().replace(/\s+/g, '');
        return clean === 'moistian' || clean === 'moistians';
      },
      errorHint: "Incorrect answer! (e.g. MOISTIAN)"
    },
    4: {
      num: 4,
      code: "MOIST-VIP-004",
      question: "What year was MOIST established?",
      example: "(e.g. <em>2001</em>)",
      placeholder: "e.g. 2001",
      validate: (input) => {
        const clean = input.trim().toLowerCase().replace(/\s+/g, '');
        return clean === '2001';
      },
      errorHint: "Incorrect year! (e.g. 2001)"
    },
    5: {
      num: 5,
      code: "MOIST-VIP-005",
      question: "Who is the Vice President for Academic Affairs at MOIST? (Or how many programs offered?)",
      example: "(e.g. <em>Dr. Julius Sol O. Jamero</em> or <em>9</em>)",
      placeholder: "e.g. Dr. Julius Sol O. Jamero or 9",
      validate: (input) => {
        const clean = input.trim().toLowerCase().replace(/\s+/g, ' ').replace(/[\.\,]/g, '');
        const validVPs = [
          'dr julius sol o jamero',
          'julius sol o jamero',
          'julius jamero',
          'dr julius jamero'
        ];
        return clean === '9' || clean === 'nine' || validVPs.includes(clean);
      },
      errorHint: "Incorrect answer! (e.g. Dr. Julius Sol O. Jamero or 9)"
    }
  };

  let currentAvailableTicket = null;

  async function checkTicketsAvailability() {
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/tickets?is_claimed=eq.false&select=*&order=id.asc`, { headers: HEADERS });
      const tickets = await res.json();

      if (!tickets || tickets.length === 0) {
        currentAvailableTicket = null;
        setAllClaimedState();
      } else {
        currentAvailableTicket = tickets[0];
        const activeQ = TICKET_QUESTIONS[tickets[0].id] || TICKET_QUESTIONS[1];
        
        const numTag = document.getElementById('question-num-tag');
        const textDisp = document.getElementById('question-text-display');
        const exampleDisp = document.getElementById('question-example-display');
        
        if (numTag) numTag.textContent = `Question for Ticket #${tickets[0].id}:`;
        if (textDisp) textDisp.textContent = activeQ.question;
        if (exampleDisp) exampleDisp.innerHTML = activeQ.example;
        if (presidentInput) presidentInput.placeholder = activeQ.placeholder;

        ticketStatusCount.innerHTML = `<strong>${tickets.length} of 5</strong> Free Tickets Available for THE HAUNTED HALL!`;
        bsitTicketBtn.disabled = false;
        bsitBtnText.textContent = 'CLAIM FREE INDIVIDUAL TICKET';
      }
      return tickets;
    } catch (err) {
      console.error('Error fetching tickets:', err);
    }
  }

  function setAllClaimedState() {
    ticketStatusCount.innerHTML = `<span style="color: #ff3344; font-weight: 800;">ALL 5 FREE TICKETS FOR THE HAUNTED HALL HAVE BEEN CLAIMED!</span>`;
    bsitTicketBtn.disabled = true;
    bsitBtnText.textContent = 'NOT AVAILABLE - ALREADY CLAIMED';
    questionCard.classList.add('hidden');
  }

  // REAL-TIME WEBSOCKET SUBSCRIPTION & HIGH-FREQUENCY POLLING LOOP
  if (window.supabase) {
    try {
      const supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
      supabaseClient
        .channel('public:tickets')
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'tickets' },
          () => {
            checkTicketsAvailability();
          }
        )
        .subscribe();
    } catch (e) {
      console.warn('Realtime subscription fallback:', e);
    }
  }

  // 1.5-second live polling loop so all active users see real-time updates instantly without page reload
  setInterval(checkTicketsAvailability, 1500);
  checkTicketsAvailability();

  if (bsitTicketBtn) {
    bsitTicketBtn.addEventListener('click', () => {
      questionCard.classList.remove('hidden');
      questionCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
      presidentInput.focus();
    });
  }

  if (claimBtn) {
    claimBtn.addEventListener('click', async () => {
      const inputVal = presidentInput.value;

      if (!inputVal || inputVal.trim() === '') {
        showResult('error', 'Please enter your answer before submitting!');
        return;
      }

      if (!currentAvailableTicket) {
        showResult('error', 'No tickets available at the moment!');
        return;
      }

      const activeQ = TICKET_QUESTIONS[currentAvailableTicket.id] || TICKET_QUESTIONS[1];

      if (!activeQ.validate(inputVal)) {
        showResult('error', activeQ.errorHint);
        return;
      }

      claimBtn.disabled = true;
      claimBtnText.textContent = 'CLAIMING TICKET...';

      const res = await fetch(`${SUPABASE_URL}/rest/v1/tickets?is_claimed=eq.false&select=*&order=id.asc&limit=1`, { headers: HEADERS });
      const tickets = await res.json();

      if (!tickets || tickets.length === 0) {
        setAllClaimedState();
        showResult('error', 'Sorry! The last ticket for THE HAUNTED HALL was just claimed!');
        return;
      }

      const ticketToClaim = tickets[0];

      const patchRes = await fetch(`${SUPABASE_URL}/rest/v1/tickets?id=eq.${ticketToClaim.id}`, {
        method: 'PATCH',
        headers: { ...HEADERS, 'Prefer': 'return=representation' },
        body: JSON.stringify({
          is_claimed: true,
          claimed_at: new Date().toISOString()
        })
      });

      if (patchRes.ok) {
        spawnBurst(width / 2, height / 2, 110, ['#ffd700', '#ffffff', '#ff9900']);
        playFanfareSound();

        showResult('success', `
          <div class="ticket-card-container">
            <!-- BIG SCREENSHOT PROOF BANNER -->
            <div class="screenshot-alert-banner">
              <div class="alert-text-wrapper">
                <div class="alert-main">PLEASE TAKE A SCREENSHOT NOW!</div>
                <div class="alert-sub">THIS SCREENSHOT IS YOUR OFFICIAL PROOF FOR EVENT ENTRY</div>
              </div>
            </div>

            <!-- REALISTIC PHYSICAL TICKET STUB -->
            <div class="real-ticket-stub">
              <div class="stub-notch notch-left"></div>
              <div class="stub-notch notch-right"></div>
              
              <div class="stub-header">
                <img src="logo.jpg" class="stub-logo" alt="MOIST Logo">
                <div class="stub-title-group">
                  <div class="stub-org">MISAMIS ORIENTAL INSTITUTE OF SCIENCE AND TECHNOLOGY</div>
                  <div class="stub-event">MOIST INTRAMURALS 2026-2027</div>
                </div>
              </div>

              <div class="stub-badge-row">
                <span class="stub-badge">THE HAUNTED HALL PASS</span>
                <span class="stub-badge verified">VERIFIED & CLAIMED</span>
              </div>

              <div class="stub-divider">
                <div class="stub-dashed-line"></div>
              </div>

              <div class="stub-code-section">
                <div class="stub-code-label">OFFICIAL TICKET CODE</div>
                <div class="stub-ticket-code">${ticketToClaim.code}</div>
              </div>

              <div class="stub-details-grid">
                <div class="stub-detail-item">
                  <span class="detail-label">EVENT / ATTRACTION</span>
                  <span class="detail-val">THE HAUNTED HALL</span>
                </div>
                <div class="stub-detail-item">
                  <span class="detail-label">VENUE</span>
                  <span class="detail-val">MOIST ATRIUM</span>
                </div>
                <div class="stub-detail-item">
                  <span class="detail-label">FESTIVAL YEAR</span>
                  <span class="detail-val">2026-2027</span>
                </div>
                <div class="stub-detail-item">
                  <span class="detail-label">STATUS</span>
                  <span class="detail-val active-status">VALID / ACTIVE</span>
                </div>
              </div>

              <div class="stub-footer">
                <div class="stub-barcode">||| | |||| | ||| || |||| ||| |||| | ||| |||</div>
                <div class="stub-watermark">AUTHENTIC MOIST VIP TICKET STUB</div>
              </div>
            </div>
          </div>
        `);

        presidentInput.value = '';
        claimBtn.disabled = false;
        claimBtnText.textContent = 'SUBMIT ANSWER & CLAIM';
        checkTicketsAvailability();
      } else {
        claimBtn.disabled = false;
        claimBtnText.textContent = 'SUBMIT ANSWER & CLAIM';
        showResult('error', 'Network error while claiming ticket. Please try again!');
      }
    });
  }

  function showResult(type, htmlContent) {
    ticketResult.classList.remove('hidden', 'ticket-success', 'ticket-error');
    ticketResult.classList.add(type === 'success' ? 'ticket-success' : 'ticket-error');
    ticketResult.innerHTML = htmlContent;
  }

});
